export function cardCopy(card: string, lang: Lang = "en"): CardCopy {
  const table = lang === "fr" ? FR : EN;
  return table[card] ?? EN[card] ?? { title: card, do: "", dont: "", button: "Continue" };
}

export function blockMessage(id: string, lang: Lang = "en"): string {
  return (lang === "fr" ? BLOCK_FR : BLOCK_EN)[id] ?? BLOCK_EN[id] ?? id;
}

export const COPY_CARDS = Object.keys(EN);
export const COPY_TABLES = { en: EN, fr: FR, block_en: BLOCK_EN, block_fr: BLOCK_FR };
